      // 原著全套道具与药剂库（真实事件解锁）
      const INVENTORY_DATABASE = [
        { name: '夜魔刀', icon: '🔪', type: 'weapon', unlock_event: 'E01', desc: '传说级手术刀，半米刀身，永不磨损绝对法则。' },
        { name: '强力粘合剂', icon: '🧪', type: 'potion', unlock_event: 'E01', desc: '外科手术专用生物胶，器官缝合对接存活率95%。' },
        { name: '夜医麻醉枸杞茶', icon: '🍵', type: 'potion', unlock_event: 'E02', desc: '麻药瓶装温热枸杞茶，无麻醉效果，温补气血。' },
        { name: '暴击药剂', icon: '⚡', type: 'potion', unlock_event: 'E08', desc: '猛男药剂，暴击率+100%，附带闪光秃头爆衣。' },
        { name: '血肉增生药剂', icon: '🩸', type: 'potion', unlock_event: 'E11', desc: '极速断肢重生，过量诱发血肉异变催生独立意识。' },
        { name: '恶灵显形药剂', icon: '👁️', type: 'potion', unlock_event: 'E15', desc: '打破相位壁垒，将无形恶灵幽魂强制物理实体化。' },
        { name: '爱丽丝燕尾服', icon: '🤵', type: 'armor', unlock_event: 'E22', desc: '恶灵亲手缝制，受击自动释放虚无锁链反杀。' },
