      ];

      // 原著全套道具与药剂库（真实事件解锁）
      const INVENTORY_DATABASE = [
        { name: '夜魔刀', icon: '🔪', type: 'weapon', unlock_event: 'E01', desc: '传说级手术刀，半米刀身，永不磨损绝对法则。' },
        { name: '强力粘合剂', icon: '🧪', type: 'potion', unlock_event: 'E01', desc: '外科手术专用生物胶，器官缝合对接存活率95%。' },
        { name: '夜医麻醉枸杞茶', icon: '🍵', type: 'potion', unlock_event: 'E02', desc: '麻药瓶装温热枸杞茶，无麻醉效果，温补气血。' },
        { name: '暴击药剂', icon: '⚡', type: 'potion', unlock_event: 'E08', desc: '猛男药剂，暴击率+100%，附带闪光秃头爆衣。' },
        { name: '血肉增生药剂', icon: '🩸', type: 'potion', unlock_event: 'E11', desc: '极速断肢重生，过量诱发血肉异变催生独立意识。' },
        { name: '恶灵显形药剂', icon: '👁️', type: 'potion', unlock_event: 'E15', desc: '打破相位壁垒，将无形恶灵幽魂强制物理实体化。' },
        { name: '爱丽丝燕尾服', icon: '🤵', type: 'armor', unlock_event: 'E22', desc: '恶灵亲手缝制，受击自动释放虚无锁链反杀。' },
        { name: '替死娃娃(x5)', icon: '🧸', type: 'relic', unlock_event: 'E36', desc: '承受致命伤瞬间位移免死，代价双倍剧痛(以M充能MAX)。' },
        { name: '夺萃之镰', icon: '🪓', type: 'weapon', unlock_event: 'E61', desc: '血肉神教巨镰，化作血雾折跃无敌帧，每日需嗜杀。' },
        { name: '自缚天使怜悯(盗版)', icon: '✨', type: 'potion', unlock_event: 'E70', desc: '主母口水拉丝版史诗药剂，强效压制根源级诅咒。' },
        { name: '小鱼形石子', icon: '🐟', type: 'relic', unlock_event: 'E136', desc: '喵喵兄长遗物，晶莹小鱼干之石，永恒羁绊心锚。' },
        { name: '迷雾药剂', icon: '🌫️', type: 'potion', unlock_event: 'E180', desc: '大范围遮蔽视线与灵能感知，夜医隐秘猎杀必备。' },
        { name: '血畸藤浓缩汁', icon: '🌿', type: 'potion', unlock_event: 'E193', desc: '极香食肉植物，食入后骨髓生根破体瞬间致瘫。' },
        { name: '圣十字半身铠', icon: '✝️', type: 'armor', unlock_event: 'E210', desc: '弥赛亚骑士重铠，两千年圣者祝福，抵御一切疾病。' },
        { name: '圣者的镇魔罗盘', icon: '🧭', type: 'relic', unlock_event: 'E210', desc: '精准感知定位数十公里内一切邪恶气息与恶魔。' },
        { name: '欲望母树精华泉水', icon: '💧', type: 'potion', unlock_event: 'E85', desc: '数千年自然神性源泉，稳固神魂，抗诅咒时光燃料。' }
      ];

      let currentFilter = 'all';
      let lastKnownState = FALLBACK_STATE;

      function isEventCompleted(eventId, state) {
        if (!eventId) return true;
        const anchors = state?.事件?.锚点状态 ?? {};
        const st = anchors[eventId]?.状态;
        return st === '完成' || st === '跳过' || st === '变形';
      }

      function findCancelledPair(state) {
        const anchors = state?.事件?.锚点状态 ?? {};
        for (const pair of ADVANCE_PAIRS) {
          if (anchors[pair.from]?.状态 === '取消') {
            return pair; // 需正文判定局部依赖
          }
        }
        return null;
      }

      function findActivePair(state) {
        const anchors = state?.事件?.锚点状态 ?? {};
        for (const pair of ADVANCE_PAIRS) {
          const fromState = anchors[pair.from]?.状态;
          const toState = anchors[pair.to]?.状态;
          if (['完成', '变形'].includes(fromState) && toState === '预兆') {
            return pair;
          }
        }
        return null;
      }

      function updateAdvanceButton() {
        const btn = byId('wa-v2-advance-btn');
        if (!btn) return;

        const cancelled = findCancelledPair(lastKnownState);
        if (cancelled) {
          btn.disabled = true;
          btn.textContent = '🔒 事件已取消（需正文判定局部依赖）';
          return;
        }

        const activePair = findActivePair(lastKnownState);
        if (activePair) {
          btn.disabled = writeInFlight || !mvuWritable;
          btn.textContent = `⚔️ ${activePair.label}`;
        } else {
          // 当前处于活跃事件中（如 E02 活跃）
          const curEvt = lastKnownState?.事件?.唯一活跃事件;
          if (curEvt?.事件ID === 'E02' || (curEvt?.事件ID && curEvt?.状态 === '活跃')) {
            btn.disabled = writeInFlight || !mvuWritable;
            if (curEvt.事件ID === 'E02') {
              btn.textContent = '⚔️ 结算 E02 并承接 E03·猪头魔与恶灵血婴';
            } else {
              const nextIdx = ALL_EVENT_IDS.indexOf(curEvt.事件ID) + 1;
              const nextId = ALL_EVENT_IDS[nextIdx] || '终局';
              btn.textContent = `⚔️ 结算 ${curEvt.事件ID} 并承接 ${nextId}`;
            }
          } else {
            btn.disabled = true;
            btn.textContent = '🕊️ 剧情平稳探索中 (与NPC自由对话推进)';
          }
        }
      }

      // 渲染 28 人深渊情缘卡片列表（严格依据 MVU 真实字段判断在场与解锁）
      function renderCharacters(state) {
        const list = byId('wa-v2-char-list');
        if (!list) return;

        const rels = state?.关系 ?? FALLBACK_STATE.关系 ?? {};
        const activeEvt = state?.事件?.唯一活跃事件 ?? {};
        const participants = activeEvt.参与者 ?? [];

        let filtered = CHARACTERS_METADATA.map(meta => {
          const r = rels[meta.name];

          // 解锁逻辑：MVU中解锁为true，或好感>0，或对应主线事件已完成
          const isUnlocked = Boolean(r?.解锁 === true || (typeof r?.好感 === 'number' && r.好感 > 0) || (typeof r?.好感度 === 'number' && r.好感度 > 0) || isEventCompleted(meta.unlock_event, state));

          // 在场逻辑：必须在当前活跃事件参与者中，或 MVU 显式标明在场为 true，且生存状态不是暂离/失联
          const isInScene = Boolean(participants.includes(meta.name) || r?.在场 === true);
          const isActive = isUnlocked && isInScene && r?.生存状态 !== '暂离' && r?.生存状态 !== '失联';

          return {
            ...meta,
            aff: typeof r?.好感 === 'number' ? r.好感 : (typeof r?.好感度 === 'number' ? r.好感度 : (isUnlocked ? meta.aff : 0)),
            corr: typeof r?.涩涩度 === 'number' ? r.涩涩度 : (typeof r?.恶堕 === 'number' ? r.恶堕 : (typeof r?.崩坏值 === 'number' ? r.崩坏值 : (isUnlocked ? meta.corr : 0))),
            status: r?.生存状态 ?? (isUnlocked ? '活动' : '未登场'),
            is_unlocked: isUnlocked,
            is_active: isActive
          };
        });

        if (currentFilter === 'active') filtered = filtered.filter(c => c.is_active);
        else if (currentFilter === 'heroines') filtered = filtered.filter(c => c.group === 'heroines');
        else if (currentFilter === 'elders') filtered = filtered.filter(c => c.group === 'elders');
        else if (currentFilter === 'comrades') filtered = filtered.filter(c => c.group === 'comrades');

        // 在场角色排在最前，已解锁排第二，未解锁排最后
        filtered.sort((a, b) => {
          if (a.is_active !== b.is_active) return b.is_active ? 1 : -1;
          if (a.is_unlocked !== b.is_unlocked) return b.is_unlocked ? 1 : -1;
          return 0;
        });

        list.innerHTML = filtered.map(c => {
          if (!c.is_unlocked) {
            return `
              <div class="dc-char-card is-locked" data-char-name="${c.name}">
                <div class="dc-char-head-row">
                  <div class="dc-char-name" style="color:var(--dc-text-muted);">${c.name} <span style="font-size:0.7rem; color:var(--dc-text-muted);">🔒 尚未结识</span></div>
                  <span class="dc-char-title" style="border-color:rgba(255,255,255,0.1); color:var(--dc-text-muted);">未登场</span>
                </div>
                <div class="dc-char-avatar-box">
                  <div class="dc-char-icon-frame" style="border-color:var(--dc-text-muted); opacity:0.4;">❓</div>
                  <div style="font-size:0.75rem; color:var(--dc-text-muted); line-height:1.4;">
                    <div>（随主线推进至 ${c.unlock_event} 时解锁）</div>
                  </div>
                </div>
              </div>
            `;
          }

          return `
            <div class="dc-char-card ${c.is_active ? 'is-active-scene' : ''}" data-char-name="${c.name}">
              <div class="dc-char-head-row">
                <div class="dc-char-name">${c.name} ${c.is_active ? '<span style="color:var(--dc-soul-emerald); font-size:0.75rem;">⚡在场</span>' : ''}</div>
                <span class="dc-char-title">${c.title}</span>
              </div>
              <div class="dc-char-avatar-box">
                <div class="dc-char-icon-frame">${c.icon}</div>
                <div style="font-size:0.78rem; color:var(--dc-text-sub); line-height:1.4;">
                  <div style="color:var(--dc-text-bright); font-style:italic;">“${c.quote}”</div>
                </div>
              </div>
              <div class="dc-track-row">
                <div class="dc-track-item">
                  <span class="dc-track-label">💖 羁绊好感</span>
                  <div class="dc-track-bar-bg"><div class="dc-track-fill-aff" style="width: ${Math.min(100, c.aff)}%;"></div></div>
                  <span class="dc-track-num">${c.aff}</span>
                </div>
                <div class="dc-track-item">
                  <span class="dc-track-label">🖤 调教恶堕</span>
                  <div class="dc-track-bar-bg"><div class="dc-track-fill-corr" style="width: ${Math.min(100, c.corr)}%;"></div></div>
                  <span class="dc-track-num">${c.corr}</span>
                </div>
              </div>
            </div>
          `;
        }).join('');

        // 绑定卡片点击弹出详情
        list.querySelectorAll('.dc-char-card').forEach(card => {
          card.addEventListener('click', () => {
            const name = card.getAttribute('data-char-name');
            const data = filtered.find(c => c.name === name);
            if (data && data.is_unlocked) openCharModal(data);
          });
        });
      }

      function openCharModal(c) {
        byId('wa-modal-char-name').textContent = `${c.name} · ${c.title}`;
        byId('wa-modal-char-content').innerHTML = `
          <p style="margin-bottom: 0.75rem; color: var(--dc-text-bright); font-weight:700;">【原声金句语料】</p>
          <blockquote style="padding: 0.5rem 0.75rem; background: rgba(0,0,0,0.4); border-left: 3px solid var(--dc-sacred-gold); margin-bottom: 1rem; font-style: italic; color: #fff;">
            “${c.quote}”
          </blockquote>
          <p style="margin-bottom: 0.5rem; color: var(--dc-sacred-gold); font-weight:700;">【角色本质与二次思考】</p>
          <p style="margin-bottom: 1rem; line-height:1.6;">${c.desc}</p>
          <div style="display:flex; justify-content:space-between; padding:0.6rem; background:rgba(255,255,255,0.04); border-radius:8px;">
            <span>💖 当前好感度: <b style="color:#fb7185;">${c.aff}</b></span>
            <span>🖤 恶堕/调教值: <b style="color:#c084fc;">${c.corr}</b></span>
          </div>
        `;
        byId('wa-v2-modal-backdrop').hidden = false;
      }

      byId('wa-modal-close-btn')?.addEventListener('click', () => {
        byId('wa-v2-modal-backdrop').hidden = true;
      });
      byId('wa-v2-modal-backdrop')?.addEventListener('click', (e) => {
        if (e.target === byId('wa-v2-modal-backdrop')) byId('wa-v2-modal-backdrop').hidden = true;
      });

      byId('wa-v2-char-filters')?.addEventListener('click', (e) => {
        if (e.target.classList.contains('dc-filter-chip')) {
          byId('wa-v2-char-filters').querySelectorAll('.dc-filter-chip').forEach(b => b.classList.remove('active'));
          e.target.classList.add('active');
          currentFilter = e.target.getAttribute('data-filter');
          renderCharacters(lastKnownState);
        }
      });

      // 渲染背包与道具
      function renderInventory(state) {
        const grid = byId('wa-v2-inventory-grid');
        if (!grid) return;

        const unlockedItems = INVENTORY_DATABASE.filter(item => isEventCompleted(item.unlock_event, state));

        grid.innerHTML = unlockedItems.map(it => `
          <div class="dc-item-slot" title="${it.desc}">
            <div class="dc-item-icon">${it.icon}</div>
            <div class="dc-item-name">${it.name}</div>
            <div class="dc-item-qty">已装配</div>
          </div>
        `).join('');
      }

      // Tab 切换交互
      const tabs = [...root.querySelectorAll('[role="tab"]')];
      function activateTab(next) {
        tabs.forEach(t => {
          const sel = t === next;
          t.setAttribute('aria-selected', String(sel));
          t.tabIndex = sel ? 0 : -1;
          const panel = byId(t.getAttribute('aria-controls'));
          if (panel) panel.hidden = !sel;
        });
      }
      tabs.forEach(tab => {
        tab.addEventListener('click', () => activateTab(tab));
      });

      // 六面骰交互
      root.querySelectorAll('.dc-dice-face').forEach(face => {
        face.addEventListener('click', () => {
          root.querySelectorAll('.dc-dice-face').forEach(f => f.classList.remove('active'));
          face.classList.add('active');
        });
      });

      // 动态自适应危机挂件渲染
      function renderHazards(state) {
        const wrap = byId('wa-v2-hazards-box');
        if (!wrap) return;

        const linen = state?.林恩 ?? {};
        const activeHazards = [];

        if ((linen.狂乱度 ?? 0) > 0) {
          activeHazards.push({ label: '🎭 小丑狂乱', val: linen.狂乱度, color: 'var(--dc-crimson-blood)' });
        }
        if ((linen.欲望值 ?? 0) > 0) {
          activeHazards.push({ label: '🌳 母树欲望', val: linen.欲望值, color: 'var(--dc-void-purple)' });
        }
        if (linen.巨像维生 === true) {
          activeHazards.push({ label: '🩸 巨像外挂血管', val: '供能中', color: 'var(--dc-cyber-blue)' });
        }
        if ((linen.咒瞳负载 ?? 0) > 0) {
          activeHazards.push({ label: '👁️ 咒瞳负载', val: linen.咒瞳负载 + '%', color: 'var(--dc-sacred-gold)' });
        }

        if (activeHazards.length === 0) {
          wrap.innerHTML = '<div class="dc-hazard-badge dc-hazard-badge--peace">✨ 身心状态稳定 · 暂无神性失控危机</div>';
        } else {
          wrap.innerHTML = activeHazards.map(h => `
            <div class="dc-hazard-badge" style="border-color:${h.color}; color:${h.color};">
              <span>${h.label}: ${h.val}</span>
            </div>
          `).join('');
        }
      }

      function updateUI(state) {
        lastKnownState = state || FALLBACK_STATE;

        // 渲染阶段与坐标（真实 S0 / E02 状态）
        const world = lastKnownState.世界 ?? {};
        const env = lastKnownState.环境 ?? {};
        const evt = lastKnownState.事件?.唯一活跃事件 ?? {};
        const linen = lastKnownState.林恩 ?? {};

        const phaseName = world.阶段名称 || world.宏观阶段 || 'S0·药店接管期';
        const phaseDesc = world.阶段目标 || '黑夜城初醒接管药剂店，在游魂巷开启药剂师与急救生涯。';
        const loc = (world.地点 || env.地点 || '游魂巷 · 血锯药剂店') + ' · ' + (env.微观场景 || '药剂店门前');
        const timeDesc = world.当前场景时间 || env.时间流逝 || 'E02收尾 · 午后的药剂店';

        if (byId('wa-v2-phase')) byId('wa-v2-phase').textContent = phaseName;
        if (byId('wa-v2-phase-desc')) byId('wa-v2-phase-desc').textContent = phaseDesc;
        if (byId('wa-v2-location')) byId('wa-v2-location').textContent = loc;
        if (byId('wa-v2-time')) byId('wa-v2-time').textContent = timeDesc;

        // 渲染身份
        if (byId('wa-v2-identity-badge')) {
          const idents = Array.isArray(linen.当前身份) ? linen.当前身份.join(' · ') : (linen.当前身份 || '血锯学徒 · 临时店主');
          byId('wa-v2-identity-badge').textContent = idents;
        }

        // 渲染主线事件
        if (byId('wa-v2-hero-evt-title')) byId('wa-v2-hero-evt-title').textContent = (evt.事件ID || 'E02') + '·' + (evt.标题 || '血娃娃上门与找妈妈任务');
        if (byId('wa-v2-hero-evt-desc')) byId('wa-v2-hero-evt-desc').textContent = evt.进展 || '血娃娃诊疗已完成：从胃中物理取出洋娃娃断臂并缝合，收右眼作抵押，触发隐藏任务‘血娃娃找妈妈’（完成度2%）；盘中留有不知名女人的头发、耳朵与梳子。血娃娃外出找妈妈。';

        // 咒瞳六面骰显示门控：未魔改前隐藏，魔改后显示
        const diceUnlocked = isEventCompleted('E173', lastKnownState) || (linen.咒瞳状态 && linen.咒瞳状态.includes('魔改'));
        if (byId('wa-v2-dice-container') && byId('wa-v2-dice-placeholder')) {
          if (diceUnlocked) {
            byId('wa-v2-dice-container').style.display = 'grid';
            byId('wa-v2-dice-placeholder').style.display = 'none';
            if (byId('wa-v2-dice-status-badge')) {
              byId('wa-v2-dice-status-badge').textContent = '真·神选史诗魔改版';
              byId('wa-v2-dice-status-badge').style.color = 'var(--dc-sacred-gold)';
            }
          } else {
            byId('wa-v2-dice-container').style.display = 'none';
            byId('wa-v2-dice-placeholder').style.display = 'block';
            if (byId('wa-v2-dice-status-badge')) {
              byId('wa-v2-dice-status-badge').textContent = '尚未觉醒/未解锁';
              byId('wa-v2-dice-status-badge').style.color = 'var(--dc-text-sub)';
            }
          }
        }

        // 渲染危机挂件、人物、道具与推进按钮
        renderHazards(lastKnownState);
        renderCharacters(lastKnownState);
        renderInventory(lastKnownState);
        updateAdvanceButton();
      }

      // 初始化渲染
      updateUI(FALLBACK_STATE);

      // MVU Bridge 连接监听
      async function connectMvu() {
        if (typeof waitForMvuBridge === 'function') {
          try {
            const mvu = await waitForMvuBridge();
            if (mvu) {
              mvuAvailable = true;
              mvuWritable = typeof mvu.replaceMvuData === 'function';
              if (mvu.getMvuData) {
                const liveData = mvu.getMvuData();
                if (liveData) updateUI(liveData);
              }
              if (mvu.events && typeof eventOn === 'function') {
                const refresh = () => {
                  if (mvu.getMvuData) updateUI(mvu.getMvuData());
                };
                eventOn(mvu.events.VARIABLE_INITIALIZED, refresh);
                eventOn(mvu.events.VARIABLE_UPDATE_ENDED, refresh);
              }
            }
          } catch (e) {
            console.warn('MVU Bridge 降级使用初始状态');
          }
        }
      }
      void connectMvu();
    })();
  </script>
</section>
</body>
